<?php require '../config.php';admin();$users=$db->query("SELECT id,name,email,balance,created_at FROM users ORDER BY id DESC");?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Users</title><link rel="stylesheet" href="../assets/style.css"></head><body><div class="app"><?php include __DIR__ . "/_sidebar.php"; ?><main class="main"><h1>Users</h1><div class="card table-wrap"><table><tr><th>ID</th><th>Name</th><th>Email</th><th>Balance</th><th>Joined</th></tr><?php while($u=$users->fetch_assoc()):?><tr><td><?=$u['id']?></td><td><?=e($u['name'])?></td><td><?=e($u['email'])?></td><td>Rs. <?=number_format($u['balance'],2)?></td><td><?=$u['created_at']?></td></tr><?php endwhile;?></table></div></main></div></body></html>